import string

dic = {}
lines = str(input().split('\n'))

for line in lines:
	if line in dic:
		dic[line] += 1
	else:
		dic[line] = 1

max = 0
for key in dic:
	if dic[key] > max:
		max = dic[key]

print(max)

n=int(input())
b=[input() for _ in range(n)]
ans=0
for i in range(n):
    for x in range(2):
        cur=0
        for j in range(i,n):
            u=[int(b[j][0])^x^int(b[i][0])]
            cur += 1
            for k in range(1,n):
                u+=[int(b[j][k])^x^int(b[i][k])]
                if u[-1]!=u[-2]:
                    cur -= 1
                    break
        ans = max(ans,cur)
print(ans)
